        @include menu-icon-position(left);
      }

      // Icon Right
      &.icon-right {
        @include menu-icon-position(right);
      }

      // Icon Top
      &.icon-top {
        @include menu-icon-position(top);
      }

      // Icon Bottom
      &.icon-bottom {
        @include menu-icon-position(bottom);
