				cursor: pointer;
				font-family: "aktiv-grotesk-extended", sans-serif;
				font-weight: 600;
				font-style: normal;
				font-size: 15px;
				letter-spacing: 2.25px;
				padding: 16px 20px;
				text-transform: uppercase;
				transition: .25s ease-in-out !important;
				&:hover,
				&:focus,
				&:active {
					background: $white;
					border: 1px solid $black;
					color: $black;
